    ar: 'وضع الرسم: اضغط واسحب على الصفحة لإنشاء عنصر، ثم اتركه لضبطه. اسحب العناصر لنقلها؛ واستخدم مقبض الزاوية لتغيير حجمها. تُرسم العناصر في ملف PDF بشكل دائم — التغطيات البيضاء تغطي المحتوى بصريًا لكنها لا تمحوه بأمان (استخدم "حجب PDF" للإزالة الحقيقية).',
    ru: 'Режим рисования: нажмите и проведите по странице, чтобы создать элемент, затем отпустите, чтобы настроить его. Перетаскивайте элементы для перемещения; используйте угловой маркер для изменения размера. Элементы встраиваются в PDF навсегда — закраски закрывают содержимое визуально, но не удаляют его надёжно (для настоящего удаления используйте «Редактирование PDF»).',
