    fr: 'L’OCR s’exécute entièrement dans votre navigateur avec le moteur Tesseract — la première utilisation télécharge les données de langue (~10 Mo). La précision dépend de la qualité de numérisation ; documents en anglais uniquement pour le moment.',
    ar: 'يعمل التعرف الضوئي بالكامل في متصفحك باستخدام محرك Tesseract — يقوم التشغيل الأول بتنزيل بيانات اللغة (~10 ميجابايت). تعتمد الدقة على جودة المسح الضوئي؛ المستندات الإنجليزية فقط في الوقت الحالي.',
    ru: 'OCR выполняется полностью в вашем браузере с помощью движка Tesseract — при первом запуске загружаются языковые данные (~10 МБ). Точность зависит от качества сканирования; пока только документы на английском языке.',
