  editDoneResult: { en: 'Done — {count} element(s) added. Your edited PDF is downloading.', es: 'Listo: se añadieron {count} elementos. Tu PDF editado se está descargando.', fr: 'Terminé — {count} élément(s) ajouté(s). Votre PDF modifié est en cours de téléchargement.', ar: 'تم — تمت إضافة {count} عناصر. يتم تنزيل ملف PDF المعدّل.', ru: 'Готово — добавлено элементов: {count}. Ваш отредактированный PDF загружается.' },
  errEditApply: { en: 'Could not apply the edits to this PDF.', es: 'No se pudieron aplicar los cambios a este PDF.', fr: 'Impossible d’appliquer les modifications à ce PDF.', ar: 'تعذر تطبيق التعديلات على ملف PDF هذا.', ru: 'Не удалось применить правки к этому PDF.' },
  editChoose2: { en: 'Choose a PDF above, then click anywhere on the page preview to place elements.', es: 'Elige un PDF arriba y luego haz clic en cualquier parte de la vista previa para colocar elementos.', fr: 'Choisissez un PDF ci-dessus, puis cliquez n’importe où sur l’aperçu de la page pour placer des éléments.', ar: 'اختر ملف PDF أعلاه، ثم انقر في أي مكان على معاينة الصفحة لوضع العناصر.', ru: 'Выберите PDF выше, затем щёлкните в любом месте предпросмотра страницы, чтобы разместить элементы.' },
