  typeTextPlaceholder: { en: 'Type text, then click the page', es: 'Escribe el texto y luego haz clic en la página', fr: 'Saisissez le texte, puis cliquez sur la page', ar: 'اكتب النص، ثم انقر على الصفحة', ru: 'Введите текст, затем щёлкните по странице' },
  fontSizePt: { en: 'Font size (pt)', es: 'Tamaño de fuente (pt)', fr: 'Taille de police (pt)', ar: 'حجم الخط (نقطة)', ru: 'Размер шрифта (пт)' },
