  imageReady: { en: 'Image ready — click the page to place it.', es: 'Imagen lista: haz clic en la página para colocarla.', fr: 'Image prête — cliquez sur la page pour la placer.', ar: 'الصورة جاهزة — انقر على الصفحة لوضعها.', ru: 'Изображение готово — щёлкните по странице, чтобы разместить его.' },
