  typeTab: { en: 'Type', es: 'Escribir', fr: 'Saisir', ar: 'كتابة', ru: 'Печать' },
  errDrawSignature: { en: 'Draw your signature in the box first.', es: 'Dibuja primero tu firma en el recuadro.', fr: 'Dessinez d’abord votre signature dans le cadre.', ar: 'ارسم توقيعك في المربع أولًا.', ru: 'Сначала нарисуйте подпись в поле.' },
  errTypeName: { en: 'Type your name first so it can be rendered as a signature.', es: 'Escribe primero tu nombre para que se pueda generar como firma.', fr: 'Saisissez d’abord votre nom pour qu’il puisse être rendu sous forme de signature.', ar: 'اكتب اسمك أولًا حتى يمكن عرضه كتوقيع.', ru: 'Сначала введите ваше имя, чтобы его можно было отобразить как подпись.' },
  errUploadSignature: { en: 'Upload a signature image first.', es: 'Sube primero una imagen de tu firma.', fr: 'Importez d’abord une image de signature.', ar: 'ارفع صورة توقيع أولًا.', ru: 'Сначала загрузите изображение подписи.' },
  errChoosePdfFirst: { en: 'Choose a PDF first.', es: 'Elige primero un PDF.', fr: 'Choisissez d’abord un PDF.', ar: 'اختر ملف PDF أولًا.', ru: 'Сначала выберите PDF.' },
  signStamping: { en: 'Stamping your signature onto the PDF…', es: 'Estampando tu firma en el PDF…', fr: 'Apposition de votre signature sur le PDF…', ar: 'جارٍ ختم توقيعك على ملف PDF…', ru: 'Проставление вашей подписи на PDF…' },
  signedDownloaded: { en: 'Signed PDF downloaded.', es: 'PDF firmado descargado.', fr: 'PDF signé téléchargé.', ar: 'تم تنزيل ملف PDF الموقّع.', ru: 'Подписанный PDF загружен.' },
  errSignFailed: { en: 'Could not sign this PDF.', es: 'No se pudo firmar este PDF.', fr: 'Impossible de signer ce PDF.', ar: 'تعذر توقيع ملف PDF هذا.', ru: 'Не удалось подписать этот PDF.' },
