  signaturePreviewAlt: { en: 'Signature preview', es: 'Vista previa de la firma', fr: 'Aperçu de la signature', ar: 'معاينة التوقيع', ru: 'Предпросмотр подписи' },
  signatureImageLabel: { en: 'Signature image (PNG with transparency works best)', es: 'Imagen de la firma (PNG con transparencia funciona mejor)', fr: 'Image de la signature (le PNG avec transparence fonctionne le mieux)', ar: 'صورة التوقيع (PNG مع الشفافية يعمل بشكل أفضل)', ru: 'Изображение подписи (лучше всего PNG с прозрачностью)' },
  centerOfPage: { en: 'Center of page', es: 'Centro de la página', fr: 'Centre de la page', ar: 'وسط الصفحة', ru: 'Центр страницы' },
