  summaryDetailedOpt: { en: 'Detailed — full summary', es: 'Detallado: resumen completo', fr: 'Détaillé — résumé complet', ar: 'مفصل — ملخص كامل', ru: 'Подробно — полное резюме' },
  summaryBulletsOpt: { en: 'Bullet key points', es: 'Puntos clave con viñetas', fr: 'Points clés en puces', ar: 'نقاط رئيسية بنقاط', ru: 'Ключевые пункты списком' },
  extractSummarizeBtn: { en: 'Extract & summarize', es: 'Extraer y resumir', fr: 'Extraire et résumer', ar: 'الاستخراج والتلخيص', ru: 'Извлечь и резюмировать' },
  translatingChunk: { en: 'Translating chunk {n} of {total} to {lang}…', es: 'Traduciendo fragmento {n} de {total} a {lang}…', fr: 'Traduction du fragment {n} sur {total} vers {lang}…', ar: 'جارٍ ترجمة الجزء {n} من {total} إلى {lang}…', ru: 'Перевод фрагмента {n} из {total} на {lang}…' },
  translationReady: { en: 'Translation to {lang} is ready below.', es: 'La traducción a {lang} está lista abajo.', fr: 'La traduction vers {lang} est prête ci-dessous.', ar: 'الترجمة إلى {lang} جاهزة أدناه.', ru: 'Перевод на {lang} готов ниже.' },
  errTranslateFailed: { en: 'Translation failed. Check your API key and connection.', es: 'La traducción falló. Comprueba tu clave de API y tu conexión.', fr: 'La traduction a échoué. Vérifiez votre clé API et votre connexion.', ar: 'فشلت الترجمة. تحقق من مفتاح API والاتصال.', ru: 'Перевод не удался. Проверьте ключ API и подключение.' },
  errTranslatedPdf: { en: 'Could not build the translated PDF.', es: 'No se pudo crear el PDF traducido.', fr: 'Impossible de créer le PDF traduit.', ar: 'تعذر إنشاء ملف PDF المترجم.', ru: 'Не удалось создать переведённый PDF.' },
  translatedToTitle: { en: 'Translated to {lang} — {name}', es: 'Traducido a {lang}: {name}', fr: 'Traduit vers {lang} — {name}', ar: 'مترجم إلى {lang} — {name}', ru: 'Переведено на {lang} — {name}' },
