  unicodeFontNote: { en: 'The translated script needs a Unicode font for PDF export — use the .txt download.', es: 'La escritura traducida necesita una fuente Unicode para exportar a PDF: usa la descarga .txt.', fr: 'L’écriture traduite nécessite une police Unicode pour l’export PDF — utilisez le téléchargement .txt.', ar: 'تحتاج الكتابة المترجمة إلى خط Unicode لتصدير PDF — استخدم تنزيل .txt.', ru: 'Для экспорта переведённого письма в PDF нужен шрифт Unicode — используйте загрузку .txt.' },

