  tiffPdfHint2: { en: 'Multi-page TIFFs become multi-page PDFs; multiple files are appended in order', es: 'Los TIFF multipágina se convierten en PDF multipágina; varios archivos se añaden en orden', fr: 'Les TIFF multipages deviennent des PDF multipages ; plusieurs fichiers sont ajoutés dans l’ordre', ar: 'تصبح ملفات TIFF متعددة الصفحات ملفات PDF متعددة الصفحات؛ وتُلحق الملفات المتعددة بالترتيب', ru: 'Многостраничные TIFF становятся многостраничными PDF; несколько файлов добавляются по порядку' },
