  coveredDone: { en: 'Covered {areas}. The rest of the document stays fully vector-sharp and searchable.', es: 'Se cubrieron {areas}. El resto del documento se mantiene totalmente nítido, vectorial y con búsqueda.', fr: '{areas} couvertes. Le reste du document reste entièrement net, vectoriel et consultable.', ar: 'تمت تغطية {areas}. يبقى باقي المستند حادًا ومتجهيًا بالكامل وقابلًا للبحث.', ru: 'Закрыто {areas}. Остальная часть документа остаётся полностью чёткой, векторной и доступной для поиска.' },
  errApplyPatches: { en: 'Could not apply the patches to this PDF.', es: 'No se pudieron aplicar los parches a este PDF.', fr: 'Impossible d’appliquer les caches à ce PDF.', ar: 'تعذر تطبيق الرقع على ملف PDF هذا.', ru: 'Не удалось применить заплатки к этому PDF.' },
  coverIntro: { en: 'Draw opaque patches over watermark text or logos. Unlike full-page redaction tools, this keeps the rest of the page as sharp vector content. The patch only covers the watermark visually — on documents where the watermark is a separate annotation or optional-content layer, it may still exist underneath the patch.', es: 'Dibuja parches opacos sobre el texto o los logotipos de marcas de agua. A diferencia de las herramientas de redacción de página completa, esto mantiene el resto de la página como contenido vectorial nítido. El parche solo cubre la marca de agua visualmente: en documentos donde la marca de agua es una anotación separada o una capa de contenido opcional, puede seguir existiendo bajo el parche.', fr: 'Dessinez des caches opaques sur le texte ou les logos en filigrane. Contrairement aux outils de masquage de page entière, cela conserve le reste de la page sous forme de contenu vectoriel net. Le cache ne couvre le filigrane que visuellement — sur les documents où le filigrane est une annotation séparée ou une couche de contenu optionnel, il peut toujours exister sous le cache.', ar: 'ارسم رقعًا معتمة فوق نص العلامة المائية أو شعاراتها. على عكس أدوات الحجب للصفحة الكاملة، يحافظ هذا على بقية الصفحة كمحتوى متجه حاد. تغطي الرقعة العلامة المائية بصريًا فقط — في المستندات التي تكون فيها العلامة المائية تعليقًا منفصلًا أو طبقة محتوى اختيارية، قد تظل موجودة أسفل الرقعة.', ru: 'Рисуйте непрозрачные заплатки поверх текста или логотипов водяных знаков. В отличие от инструментов редактирования всей страницы, это сохраняет остальную часть страницы как чёткое векторное содержимое. Заплатка закрывает водяной знак только визуально — в документах, где водяной знак является отдельной аннотацией или слоем необязательного содержимого, он может всё ещё существовать под заплаткой.' },
  patchColor: { en: 'Patch color', es: 'Color del parche', fr: 'Couleur du cache', ar: 'لون الرقعة', ru: 'Цвет заплатки' },
  patchColorNote: { en: 'Use white for most documents; match the page background for colored pages.', es: 'Usa blanco para la mayoría de los documentos; iguala el fondo de la página para páginas de colores.', fr: 'Utilisez le blanc pour la plupart des documents ; adaptez-vous à l’arrière-plan de la page pour les pages colorées.', ar: 'استخدم الأبيض لمعظم المستندات؛ وطابق خلفية الصفحة للصفحات الملونة.', ru: 'Используйте белый для большинства документов; для цветных страниц подбирайте цвет под фон страницы.' },
  coverChoose: { en: 'Choose a PDF above, then drag boxes over the watermark on each page.', es: 'Elige un PDF arriba y luego arrastra recuadros sobre la marca de agua en cada página.', fr: 'Choisissez un PDF ci-dessus, puis faites glisser des cadres sur le filigrane de chaque page.', ar: 'اختر ملف PDF أعلاه، ثم اسحب مربعات فوق العلامة المائية في كل صفحة.', ru: 'Выберите PDF выше, затем проведите прямоугольники поверх водяного знака на каждой странице.' },
  applyingLabel: { en: 'Applying…', es: 'Aplicando…', fr: 'Application…', ar: 'جارٍ التطبيق…', ru: 'Применение…' },
  coverBtnTpl: { en: 'Cover {areas} & Download', es: 'Cubrir {areas} y descargar', fr: 'Couvrir {areas} et télécharger', ar: 'تغطية {areas} والتنزيل', ru: 'Закрыть {areas} и скачать' },
  removeAnnotationsAction: { en: 'Remove annotations', es: 'Eliminar anotaciones', fr: 'Supprimer les annotations', ar: 'إزالة التعليقات التوضيحية', ru: 'Удалить аннотации' },
  splitDirection: { en: 'Split direction', es: 'Dirección de división', fr: 'Direction de division', ar: 'اتجاه التقسيم', ru: 'Направление разделения' },
