  rangePlaceholderEx: { en: 'e.g. 1-3, 5, 8-10', es: 'ej. 1-3, 5, 8-10', fr: 'ex. 1-3, 5, 8-10', ar: 'مثال: 1-3، 5، 8-10', ru: 'например, 1-3, 5, 8-10' },
  extractIntoNewPdf: { en: 'Extracted {pages} into a new PDF.', es: 'Se extrajeron {pages} a un nuevo PDF.', fr: '{pages} extraites dans un nouveau PDF.', ar: 'تم استخراج {pages} إلى ملف PDF جديد.', ru: 'Извлечено {pages} в новый PDF.' },
  errNoValidPagesRange: { en: 'No valid pages in that range — this PDF has {pages}.', es: 'No hay páginas válidas en ese rango: este PDF tiene {pages}.', fr: 'Aucune page valide dans cette plage — ce PDF contient {pages}.', ar: 'لا توجد صفحات صالحة في هذا النطاق — يحتوي ملف PDF هذا على {pages}.', ru: 'В этом диапазоне нет допустимых страниц — в этом PDF {pages}.' },
  buildingYourPdf: { en: 'Building your PDF…', es: 'Creando tu PDF…', fr: 'Création de votre PDF…', ar: 'جارٍ إنشاء ملف PDF الخاص بك…', ru: 'Создание вашего PDF…' },
